INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM204KQAO', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'grid_in', E'When $\\frac{3}{4}$ of a number is decreased by $7$, the result is equal to $\\frac{1}{2}$ of the number increased by $3$. What is the number?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '40', ARRAY['40'], E'Let the number be $n$. The equation is $\\frac{3}{4}n - 7 = \\frac{1}{2}n + 3$. Subtract $\\frac{1}{2}n$ from both sides to get $\\frac{3}{4}n - \\frac{1}{2}n - 7 = 3$. Since $\\frac{3}{4} - \\frac{1}{2} = \\frac{1}{4}$, this simplifies to $\\frac{1}{4}n - 7 = 3$. Adding $7$ to both sides gives $\\frac{1}{4}n = 10$, and multiplying both sides by $4$ gives $n = 40$. A common error is finding a common denominator incorrectly or making a sign error when moving $\\frac{1}{2}n$ to the left side, which leads to an incorrect value.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20FY0BO', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = x^2 + 3$. What is the value of $f(2)$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$7$"},{"key":"C","text":"$10$"},{"key":"D","text":"$9$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $x = 2$ gives $f(2) = (2)^2 + 3 = 4 + 3 = 7$. The value $5$ results from computing $2 + 3$ without squaring the input first. The value $10$ comes from computing $2^2 \\times 3 = 12$ or another order-of-operations error that conflates addition with multiplication. The value $9$ results from squaring $3$ instead of $2$, giving $3^2 = 9$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
