INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21EHJZ7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher collects data on the age (in years) and value (in thousands of dollars) of used cars. The line of best fit is $v = -1.8a + 28$, where $v$ is the predicted value and $a$ is the age. According to this model, what is the predicted value, in thousands of dollars, of a car that is $6$ years old?', NULL, $lyceon_json$[{"key":"A","text":"$10.8$"},{"key":"B","text":"$17.2$"},{"key":"C","text":"$28$"},{"key":"D","text":"$38.8$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $a = 6$ into $v = -1.8(6) + 28 = -10.8 + 28 = 17.2$. The predicted value is $17.2$ thousand dollars. The result $10.8$ is the magnitude of $1.8 \\times 6$ alone, stopping before adding the intercept. The result $28$ is just the $y$-intercept, which ignores the age input entirely. The result $38.8$ comes from adding $10.8$ to $28$ instead of subtracting, a sign error with the negative slope.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22RIFBZ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'How many real solutions does the equation $x^2 - 6x + 10 = 0$ have?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$1$"},{"key":"C","text":"$2$"},{"key":"D","text":"$3$"}]$lyceon_json$::jsonb, 'A', NULL, E'The discriminant is $b^2 - 4ac = (-6)^2 - 4(1)(10) = 36 - 40 = -4$. Since the discriminant is negative, the equation has $0$ real solutions. Choosing $1$ reflects confusion with the condition for a repeated root, which requires the discriminant to equal exactly zero. Choosing $2$ reflects the incorrect assumption that every quadratic equation has two real solutions. Choosing $3$ reflects a fundamental misunderstanding, since a quadratic equation can have at most two solutions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23SYTSV', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'In right triangle $MNP$, the right angle is at vertex $N$. If $\\cos(M) = \\frac{5}{13}$ and $MP = 26$, what is the area of triangle $MNP$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '120', ARRAY['120'], E'Since $\\cos(M) = \\frac{\\text{adjacent}}{\\text{hypotenuse}} = \\frac{MN}{MP} = \\frac{5}{13}$ and $MP = 26$, we get $MN = \\frac{5}{13} \\times 26 = 10$. The side opposite angle $M$ is $NP = \\sqrt{26^2 - 10^2} = \\sqrt{676 - 100} = \\sqrt{576} = 24$. The area of the right triangle is $\\frac{1}{2} \\times MN \\times NP = \\frac{1}{2} \\times 10 \\times 24 = 120$. A common error is forgetting the $\\frac{1}{2}$ factor, giving $240$ instead of $120$. Another error is using $\\sin(M) = \\frac{5}{13}$ instead of $\\cos(M)$, which swaps the leg lengths but produces the same area.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26UWP70', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'A store offers free shipping on orders totaling more than $\\$25$. A customer has already added $\\$18$ worth of items to the cart. Which inequality represents the additional amount $x$, in dollars, the customer must add to qualify for free shipping?', NULL, $lyceon_json$[{"key":"A","text":"$x > 7$"},{"key":"B","text":"$x \\geq 7$"},{"key":"C","text":"$x > 25$"},{"key":"D","text":"$x < 7$"}]$lyceon_json$::jsonb, 'A', NULL, E'The customer needs the total to exceed $\\$25$, so $18 + x > 25$, which simplifies to $x > 7$. The distractor $x \\geq 7$ incorrectly uses a non-strict inequality; since the problem states "more than" $\\$25$, the boundary value $x = 7$ (which yields exactly $\\$25$) does not qualify. The distractor $x > 25$ ignores the $\\$18$ already in the cart and compares $x$ alone to the threshold. The distractor $x < 7$ reverses the direction of the inequality.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27K3X27', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'From an external point $P$, two secant lines are drawn to a circle. The first secant intersects the circle at points $A$ and $B$ such that $PA = 3$ and $PB = 8$. The second secant intersects the circle at points $C$ and $D$ such that $PC = 4$. What is the length of $CD$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '2', ARRAY['2'], E'By the power of a point theorem for two secants drawn from the same external point, $PA \\times PB = PC \\times PD$. Substituting: $3 \\times 8 = 4 \\times PD$, so $24 = 4 \\times PD$ and $PD = 6$. Since $C$ is between $P$ and $D$ on the secant line, $CD = PD - PC = 6 - 4 = 2$. A common error is confusing chord lengths with full secant lengths, setting up $PA \\times AB = PC \\times CD$ instead. Another error is forgetting to subtract $PC$ from $PD$ and reporting $PD = 6$ as the answer.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27P4UNI', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'Triangle $XYZ$ is similar to triangle $RST$, where $X$ corresponds to $R$ and $Y$ corresponds to $S$. If $XY = 18$, $YZ = 24$, $XZ = 30$, and $RS = 12$, what is the perimeter of triangle $RST$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '48', ARRAY['48'], E'Since the triangles are similar, the ratio of corresponding sides is constant. The ratio is $\\frac{RS}{XY} = \\frac{12}{18} = \\frac{2}{3}$. Therefore $ST = \\frac{2}{3} \\times 24 = 16$ and $RT = \\frac{2}{3} \\times 30 = 20$. The perimeter of triangle $RST$ is $12 + 16 + 20 = 48$. Alternatively, the perimeter of triangle $XYZ$ is $18 + 24 + 30 = 72$, and $72 \\times \\frac{2}{3} = 48$. A common error is inverting the scale factor to $\\frac{3}{2}$, which gives a perimeter of $108$. Another error is applying the ratio to only two sides and keeping one side unchanged.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28GVUUJ', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'What is the value of $x$ in the equation $4(x + 3) - 2(x - 1) = 22$?', NULL, $lyceon_json$[{"key":"A","text":"$-4$"},{"key":"B","text":"$3$"},{"key":"C","text":"$4$"},{"key":"D","text":"$6$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $4$. Distribute to get $4x + 12 - 2x + 2 = 22$, which simplifies to $2x + 14 = 22$. Subtracting $14$ from both sides gives $2x = 8$, so $x = 4$. The value $-4$ results from introducing a sign error in the final step. The value $6$ comes from incorrectly distributing $-2(x - 1)$ as $-2x - 2$ instead of $-2x + 2$, which leads to $2x + 10 = 22$ and $x = 6$. The value $3$ results from an arithmetic slip during simplification.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28V8Z7A', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a radius of $9$ inches. What is the area of the circle, in square inches?', NULL, $lyceon_json$[{"key":"A","text":"$18\\pi$"},{"key":"B","text":"$81\\pi$"},{"key":"C","text":"$9\\pi$"},{"key":"D","text":"$324\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The area of a circle is $A = \\pi r^2$. With $r = 9$: $A = \\pi(9)^2 = 81\\pi$ square inches. The value $18\\pi$ comes from using the circumference formula $2\\pi r = 18\\pi$ instead of the area formula. The value $9\\pi$ results from computing $\\pi r$ instead of $\\pi r^2$, omitting the squaring step. The value $324\\pi$ comes from using the diameter ($18$) in place of the radius: $\\pi(18)^2 = 324\\pi$.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2A0I1KA', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle $DEF$, the measure of angle $D$ is $38^\\circ$ and the measure of angle $F$ is $74^\\circ$. What is the measure, in degrees, of angle $E$?', NULL, $lyceon_json$[{"key":"A","text":"$58$"},{"key":"B","text":"$68$"},{"key":"C","text":"$112$"},{"key":"D","text":"$36$"}]$lyceon_json$::jsonb, 'B', NULL, E'The sum of the interior angles of a triangle is $180^\\circ$. Therefore, angle $E = 180 - 38 - 74 = 68$ degrees. The value $58$ results from an arithmetic slip in the subtraction. The value $112$ comes from adding $38 + 74 = 112$ and reporting the sum rather than subtracting it from $180$. The value $36$ results from computing $74 - 38 = 36$, the difference of the two given angles, rather than using the angle sum property.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AJXDP6', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle has its center at the point $(3, -2)$ and passes through the point $(7, 1)$. What is the radius of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$5$"},{"key":"C","text":"$7$"},{"key":"D","text":"$25$"}]$lyceon_json$::jsonb, 'B', NULL, E'The radius equals the distance from the center $(3, -2)$ to the point $(7, 1)$: $r = \\sqrt{(7 - 3)^2 + (1 - (-2))^2} = \\sqrt{4^2 + 3^2} = \\sqrt{16 + 9} = \\sqrt{25} = 5$. The value $3$ results from an arithmetic error such as computing only one component of the distance. The value $7$ comes from adding the coordinate differences ($4 + 3 = 7$) instead of using the distance formula with squares. The value $25$ comes from computing $r^2 = 25$ but not taking the square root.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AKJZRG', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A parking garage charges a flat fee of $\\$5$ plus $\\$2.50$ per hour. A driver wants to spend no more than $\\$20$ on parking. Which inequality can be used to find $h$, the maximum number of hours the driver can park?', NULL, $lyceon_json$[{"key":"A","text":"$2.50h \\leq 20$"},{"key":"B","text":"$5 + 2.50h \\leq 20$"},{"key":"C","text":"$5 + 2.50h \\geq 20$"},{"key":"D","text":"$5 + 2.50h < 20$"}]$lyceon_json$::jsonb, 'B', NULL, E'The total cost is the flat fee plus the hourly charge: $5 + 2.50h$. The phrase "no more than $\\$20$" means the total must be less than or equal to $\\$20$, giving $5 + 2.50h \\leq 20$. The distractor $2.50h \\leq 20$ omits the $\\$5$ flat fee from the total cost. The distractor $5 + 2.50h \\geq 20$ reverses the inequality, requiring the driver to spend at least $\\$20$ rather than at most. The distractor $5 + 2.50h < 20$ uses a strict inequality, which would exclude spending exactly $\\$20$; "no more than" includes equality.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BHSXK3', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'What is the positive solution to the equation $x^2 = 49$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Taking the square root of both sides of $x^2 = 49$ gives $x = 7$ or $x = -7$. Since the question asks for the positive solution, the answer is $7$. A common error is giving $-7$, which is the negative root, or $24.5$, which results from dividing $49$ by $2$ instead of taking the square root.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CHQS93', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'The system of equations $3x + ky = 12$ and $9x + 6y = 5$ has no solution. What is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$-2$"},{"key":"B","text":"$2$"},{"key":"C","text":"$6$"},{"key":"D","text":"$18$"}]$lyceon_json$::jsonb, 'B', NULL, E'A system of two linear equations has no solution when the lines are parallel: the ratios of the coefficients of $x$ and $y$ are equal, but the ratio of the constants is different. Setting the coefficient ratios equal gives $\\frac{3}{9} = \\frac{k}{6}$, so $k = 6 \\cdot \\frac{3}{9} = 2$. Checking the constants: $\\frac{12}{5} \\neq \\frac{1}{3}$, confirming no solution exists. The distractor $-2$ introduces an incorrect negative sign when computing the proportional coefficient. The distractor $6$ takes the $y$-coefficient from the second equation directly rather than computing the required ratio. The distractor $18$ results from multiplying $3 \\times 6$ instead of solving $\\frac{3}{9} = \\frac{k}{6}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DWJKUR', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A square has a side length of $11$ centimeters. What is the area of the square, in square centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$44$"},{"key":"B","text":"$121$"},{"key":"C","text":"$22$"},{"key":"D","text":"$110$"}]$lyceon_json$::jsonb, 'B', NULL, E'The area of a square is $A = s^2$. With $s = 11$: $A = 11^2 = 121$ square centimeters. The value $44$ is the perimeter ($4 \\times 11 = 44$), resulting from confusing area with perimeter. The value $22$ comes from doubling the side length ($2 \\times 11 = 22$) instead of squaring it. The value $110$ results from an arithmetic slip such as computing $11 \\times 10$ instead of $11 \\times 11$.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 35, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FRIJEE', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the slope of the line $2x + 4y = 12$?', NULL, $lyceon_json$[{"key":"A","text":"$-2$"},{"key":"B","text":"$-\\frac{1}{2}$"},{"key":"C","text":"$\\frac{1}{2}$"},{"key":"D","text":"$3$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $-\\frac{1}{2}$. Rewrite $2x + 4y = 12$ in slope-intercept form by subtracting $2x$ from both sides to get $4y = -2x + 12$, then dividing every term by $4$ to get $y = -\\frac{1}{2}x + 3$. The slope is $-\\frac{1}{2}$. The value $-2$ comes from using the coefficient of $x$ directly without dividing by the coefficient of $y$. The value $\\frac{1}{2}$ results from a sign error, dropping the negative. The value $3$ is the $y$-intercept, not the slope.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GBTNA1', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What is the value of $x$ in the equation $3x - 9 = 12$?', NULL, $lyceon_json$[{"key":"A","text":"$-7$"},{"key":"B","text":"$1$"},{"key":"C","text":"$7$"},{"key":"D","text":"$21$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $7$. Add $9$ to both sides of $3x - 9 = 12$ to get $3x = 21$, then divide both sides by $3$ to get $x = 7$. The value $-7$ results from a sign error when dividing $21$ by $3$. The value $1$ results from an arithmetic slip such as computing $12 \\div 12$. The value $21$ comes from stopping after finding $3x = 21$ without dividing by $3$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GQ6RFO', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $3(x + 4) - 2(x - 1)$?', NULL, $lyceon_json$[{"key":"A","text":"$x + 14$"},{"key":"B","text":"$x + 10$"},{"key":"C","text":"$5x + 14$"},{"key":"D","text":"$x + 12$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing gives $3x + 12 - 2x + 2$. Combining like terms: $3x - 2x = x$ and $12 + 2 = 14$, so the result is $x + 14$. The expression $x + 10$ comes from incorrectly subtracting $2$ instead of adding it when distributing the negative sign through $(x - 1)$. The expression $5x + 14$ results from adding the coefficients $3$ and $2$ instead of subtracting them. The expression $x + 12$ comes from dropping the constant $+2$ that arises from $-2 \\times -1$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H0O0PQ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'A ladder leans against a vertical wall, making an angle of $65^\\circ$ with the ground. If the foot of the ladder is $4$ feet from the base of the wall, which expression gives the height on the wall that the ladder reaches, in feet?', NULL, $lyceon_json$[{"key":"A","text":"$4\\tan(65^\\circ)$"},{"key":"B","text":"$\\frac{4}{\\tan(65^\\circ)}$"},{"key":"C","text":"$4\\sin(65^\\circ)$"},{"key":"D","text":"$4\\cos(65^\\circ)$"}]$lyceon_json$::jsonb, 'A', NULL, E'The horizontal distance from the wall ($4$ feet) is the side adjacent to the $65^\\circ$ angle, and the height on the wall is the side opposite the $65^\\circ$ angle. Using $\\tan(65^\\circ) = \\frac{\\text{opposite}}{\\text{adjacent}} = \\frac{h}{4}$, solving gives $h = 4\\tan(65^\\circ)$. The expression $\\frac{4}{\\tan(65^\\circ)}$ inverts the tangent relationship. The expression $4\\sin(65^\\circ)$ incorrectly applies sine to the adjacent side rather than the hypotenuse. The expression $4\\cos(65^\\circ)$ applies cosine to the adjacent side, which does not yield the opposite side.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HG8F3P', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'The equation of line $\\ell$ is $4x + 3y = 24$. Line $\\ell$ intersects the $x$-axis at point $A$ and the $y$-axis at point $B$. What is the area of triangle $OAB$, where $O$ is the origin?', NULL, $lyceon_json$[{"key":"A","text":"$12$"},{"key":"B","text":"$14$"},{"key":"C","text":"$24$"},{"key":"D","text":"$48$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $24$. To find the $x$-intercept, set $y = 0$: $4x = 24$, so $x = 6$ and $A = (6, 0)$. To find the $y$-intercept, set $x = 0$: $3y = 24$, so $y = 8$ and $B = (0, 8)$. Triangle $OAB$ has a base of $6$ along the $x$-axis and a height of $8$ along the $y$-axis. The area is $\\frac{1}{2}(6)(8) = 24$. The value $48$ comes from computing the product $6 \\times 8$ without applying the $\\frac{1}{2}$ factor for a triangle. The value $14$ comes from adding the intercepts $6 + 8$ instead of using the area formula. The value $12$ results from using only one intercept, such as computing $\\frac{1}{2}(4)(6)$ by confusing a coefficient with an intercept.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JDA2N7', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'The equations $y = x^2 + bx + 12$ and $y = 2x + 3$ intersect at exactly one point. If $b < 0$, what is the value of $b$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-4', ARRAY['-4'], E'Setting the two equations equal gives $x^2 + bx + 12 = 2x + 3$, which simplifies to $x^2 + (b - 2)x + 9 = 0$. For exactly one intersection, the discriminant must equal zero: $(b - 2)^2 - 4(1)(9) = 0$. This gives $(b - 2)^2 = 36$, so $b - 2 = 6$ or $b - 2 = -6$, yielding $b = 8$ or $b = -4$. Since $b < 0$, the answer is $-4$. A common error is forgetting to subtract $2x + 3$ from both sides before applying the discriminant condition, or selecting $b = 8$ without checking the constraint $b < 0$.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JOAWU7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'grid_in', E'A class of $20$ students takes a test. The mean score is $74$ and the median score is $76$. The teacher discovers that one student''s score of $58$ was recorded incorrectly and should have been $68$. After correcting this score, what is the new mean of the class?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '74.5', ARRAY['149/2', '74.5'], E'The original sum of all scores is $20 \\times 74 = 1{,}480$. After correcting the score from $58$ to $68$, the sum increases by $10$, giving a new sum of $1{,}490$. The new mean is $\\frac{1{,}490}{20} = 74.5$. A common error is recalculating the median instead of the mean, or failing to recognize that changing one value shifts the sum by the difference between the new and old values. Another error is dividing by $19$ instead of $20$, forgetting that the total number of students does not change.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JWT224', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'grid_in', E'The function $g(x) = mx + 12$ models the balance, in dollars, of a savings account $x$ weeks after the account was opened. After $8$ weeks, the balance is $\\$60$. At what value of $x$ will the balance first reach $\\$150$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '23', ARRAY['23'], E'First, find $m$ by substituting $x = 8$ and $g(8) = 60$ into the function: $8m + 12 = 60$, so $8m = 48$ and $m = 6$. The function is $g(x) = 6x + 12$. To find when the balance reaches $\\$150$, solve $6x + 12 = 150$: subtract $12$ from both sides to get $6x = 138$, then divide by $6$ to get $x = 23$. A common error is finding $m$ incorrectly by dividing $60$ by $8$ to get $m = 7.5$, which ignores the initial $\\$12$. Another error is solving $6x = 150$ without subtracting $12$ first, which gives $x = 25$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KLKNYT', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'grid_in', E'A researcher surveys $900$ randomly selected households and finds that $\\hat{p} = 0.36$ of them own at least one pet. Using the formula $\\text{ME} = 1.96\\sqrt{\\frac{\\hat{p}(1 - \\hat{p})}{n}}$, what is the margin of error to the nearest hundredth?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '0.03', ARRAY['3/100', '0.03', '.03'], E'Substituting the values into the formula: $\\text{ME} = 1.96\\sqrt{\\frac{0.36 \\times 0.64}{900}}$. First compute the numerator inside the square root: $0.36 \\times 0.64 = 0.2304$. Then divide by $900$: $\\frac{0.2304}{900} = 0.000256$. Take the square root: $\\sqrt{0.000256} = 0.016$. Multiply by $1.96$: $1.96 \\times 0.016 = 0.03136$. Rounded to the nearest hundredth, the margin of error is $0.03$. A common error is forgetting to take the square root and computing $1.96 \\times 0.000256$, which yields a value far too small. Another error is using $\\hat{p}^2$ instead of $\\hat{p}(1 - \\hat{p})$, which gives an incorrect variance estimate.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KYKBEZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'Researchers randomly assigned $100$ potted tomato plants to two groups of $50$. One group received a new nutrient solution, and the other received plain water. All plants were kept in the same greenhouse under identical light and temperature conditions. After eight weeks, the group receiving the nutrient solution had a statistically significantly greater average height. Which of the following conclusions is best supported by this study?', NULL, $lyceon_json$[{"key":"A","text":"The nutrient solution caused the tomato plants to grow taller compared to plants receiving plain water."},{"key":"B","text":"The nutrient solution is associated with taller plants, but the study cannot establish causation."},{"key":"C","text":"The result is likely due to differences in sunlight exposure between the two groups."},{"key":"D","text":"The experiment must be repeated with at least $1{,}000$ plants before any conclusion can be drawn."}]$lyceon_json$::jsonb, 'A', NULL, E'This is a randomized controlled experiment: plants were randomly assigned to treatment and control groups, and all other conditions were held constant. Random assignment distributes potential confounders evenly across groups, and a statistically significant result supports a causal conclusion. The distractor claiming causation cannot be established incorrectly applies the limitation of observational studies to a properly designed experiment with random assignment. The distractor about sunlight differences is unfounded because all plants were in the same greenhouse under identical conditions. The distractor requiring $1{,}000$ plants is incorrect because the study already achieved statistical significance, indicating the sample was sufficient to detect the effect.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L94XCO', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A hospital compared recovery times of patients who chose to undergo physical therapy after knee surgery with those who did not. Patients who chose physical therapy recovered faster on average. Participation in physical therapy was the patient''s own decision. Which of the following is a valid conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Physical therapy caused the patients to recover more quickly."},{"key":"B","text":"The study proves that physical therapy has no effect because it was not a controlled experiment."},{"key":"C","text":"A larger sample size would confirm that physical therapy caused the faster recovery."},{"key":"D","text":"Patients who chose physical therapy may have differed from those who did not in ways that also affect recovery, so the difference could be due to a confounding variable."}]$lyceon_json$::jsonb, 'D', NULL, E'Because patients chose whether to participate, this is an observational study. Patients who opted for physical therapy may have been younger, more motivated, or in better overall health, creating confounding variables that could explain the faster recovery. The claim that physical therapy caused faster recovery is not supported because causation requires random assignment to eliminate confounding. The claim that the study proves no effect overstates the limitation; the study cannot establish causation, but that does not mean the treatment has no effect. The claim that a larger sample would confirm causation is incorrect because increasing sample size does not remove confounding in an observational design.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LFCMKQ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'grid_in', E'A store marks up the wholesale price of an item by $60\\%$ to set the retail price. During a sale, the store discounts the retail price by $25\\%$. The sale price of the item is $\\$48$. What is the wholesale price, in dollars, of the item?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '40', ARRAY['40'], E'Let $w$ be the wholesale price. After a $60\\%$ markup, the retail price is $1.60w$. After a $25\\%$ discount on the retail price, the sale price is $0.75 \\times 1.60w = 1.20w$. Setting $1.20w = 48$ gives $w = 40$. A common error is applying the percentages sequentially in the wrong order or confusing the markup and discount bases. Another error is computing $48 \\div 0.60 \\div 0.25$, which misunderstands that a $60\\%$ markup means multiplying by $1.60$, not by $0.60$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LZTT9Q', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A sphere has a volume of $288\\pi$ cubic centimeters. What is the radius of the sphere, in centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$6$"},{"key":"C","text":"$8$"},{"key":"D","text":"$12$"}]$lyceon_json$::jsonb, 'B', NULL, E'The volume of a sphere is $V = \\frac{4}{3}\\pi r^3$. Setting $\\frac{4}{3}\\pi r^3 = 288\\pi$ and dividing both sides by $\\pi$: $\\frac{4}{3}r^3 = 288$. Multiplying both sides by $\\frac{3}{4}$: $r^3 = 216$. Taking the cube root: $r = 6$. The value $4$ results from an arithmetic error in computing the cube root of $216$. The value $8$ comes from not applying the $\\frac{3}{4}$ multiplier correctly and approximating the cube root of $288$. The value $12$ results from omitting the $\\frac{4}{3}$ coefficient and solving $r^3 = 288 \\times 3 = 864$, then taking an incorrect cube root.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M3ZMDQ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A school cafeteria surveyed $250$ students about their lunch preference. Of the $160$ underclassmen, $100$ chose pasta. Of the $90$ upperclassmen, $35$ chose pasta. If a student who chose pasta is selected at random, what is the probability that this student is an upperclassman?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7}{27}$"},{"key":"B","text":"$\\frac{7}{18}$"},{"key":"C","text":"$\\frac{7}{50}$"},{"key":"D","text":"$\\frac{9}{25}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The question asks for a conditional probability: given that a student chose pasta, what is the probability that the student is an upperclassman? The total number of students who chose pasta is $100 + 35 = 135$. Of those, $35$ are upperclassmen, so the conditional probability is $\\frac{35}{135} = \\frac{7}{27}$. The distractor $\\frac{7}{18}$ results from dividing $35$ by $90$ (the total number of upperclassmen), which conditions on being an upperclassman rather than on choosing pasta. The distractor $\\frac{7}{50}$ divides $35$ by the total $250$ students, ignoring the condition entirely. The distractor $\\frac{9}{25}$ gives $\\frac{90}{250}$, the unconditional probability of being an upperclassman, which does not account for the pasta condition.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M578E5', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'grid_in', E'A coffee shop sells small cups for $\\$3$ each and large cups for $\\$5$ each. On a certain morning, the shop sold a total of $40$ cups and collected $\\$156$ in revenue from these sales. How many large cups were sold that morning?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '18', ARRAY['18'], E'Let $s$ represent the number of small cups and $l$ represent the number of large cups. The system of equations is $s + l = 40$ and $3s + 5l = 156$. From the first equation, $s = 40 - l$. Substituting into the second equation: $3(40 - l) + 5l = 156$, which simplifies to $120 - 3l + 5l = 156$, then $2l = 36$, so $l = 18$. Therefore $18$ large cups were sold.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M933V6', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A student received the following scores on five quizzes: $72$, $85$, $90$, $85$, $88$. What is the mode of the student''s quiz scores?', NULL, $lyceon_json$[{"key":"A","text":"$72$"},{"key":"B","text":"$84$"},{"key":"C","text":"$85$"},{"key":"D","text":"$88$"}]$lyceon_json$::jsonb, 'C', NULL, E'The mode is the value that appears most frequently. In the set $\\{72, 85, 85, 88, 90\\}$, the value $85$ appears twice while all other values appear once, so the mode is $85$. The value $72$ is the minimum, not the mode. The value $84$ is the mean, not the mode. The value $88$ appears only once and is not the most frequent.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MQXULX', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'Line $p$ passes through the points $(2, 5)$ and $(6, 13)$. What is the $y$-intercept of line $p$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '1', ARRAY['1'], E'First, find the slope of line $p$ using the slope formula: $m = \\frac{13 - 5}{6 - 2} = \\frac{8}{4} = 2$. Then use the point-slope form with the point $(2, 5)$: $y - 5 = 2(x - 2)$, which gives $y = 2x - 4 + 5 = 2x + 1$. The $y$-intercept is $1$. A common error is computing the slope incorrectly by reversing the order of subtraction in the numerator or denominator, or substituting the point coordinates incorrectly into the equation.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MSGGQ0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A car travels $180$ miles using $6$ gallons of gasoline. A truck travels $260$ miles using $13$ gallons of gasoline. How many more miles per gallon does the car get than the truck?', NULL, $lyceon_json$[{"key":"A","text":"$10$"},{"key":"B","text":"$15$"},{"key":"C","text":"$20$"},{"key":"D","text":"$30$"}]$lyceon_json$::jsonb, 'A', NULL, E'The car gets $\\frac{180}{6} = 30$ miles per gallon and the truck gets $\\frac{260}{13} = 20$ miles per gallon. The difference is $30 - 20 = 10$ miles per gallon. The result $15$ comes from averaging the two rates instead of subtracting them. The result $20$ is the truck''s rate alone, which answers the wrong question. The result $30$ is the car''s rate alone, ignoring the comparison the stem asks for.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MTV35S', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'A data set contains $7$ values: $3$, $5$, $7$, $8$, $10$, $12$, $x$. If the median of the data set is $8$ and $x > 12$, what is the mean of the data set?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{45 + x}{7}$"},{"key":"B","text":"$8$"},{"key":"C","text":"$\\frac{53}{7}$"},{"key":"D","text":"$\\frac{57}{7}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Since there are $7$ values, the median is the $4$th value when arranged in order. With $x > 12$, the ordered set is $3, 5, 7, 8, 10, 12, x$, and the $4$th value is $8$, which confirms the median condition. The mean is $\\frac{3 + 5 + 7 + 8 + 10 + 12 + x}{7} = \\frac{45 + x}{7}$. The answer $8$ confuses the mean with the median. The result $\\frac{53}{7}$ omits $x$ from the sum and miscounts. The result $\\frac{57}{7}$ comes from an arithmetic error in summing the known values.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N23VB0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A scatterplot shows the relationship between the number of hours studied and test scores for $10$ students. The line of best fit has a slope of $8$. Which of the following is the best interpretation of this slope?', NULL, $lyceon_json$[{"key":"A","text":"For each additional hour studied, the predicted test score increases by $8$ points."},{"key":"B","text":"A student who studies for $8$ hours will score $100$ on the test."},{"key":"C","text":"The average test score is $8$ points."},{"key":"D","text":"The test score increases by $1$ point for every $8$ hours studied."}]$lyceon_json$::jsonb, 'A', NULL, E'The slope of a line of best fit represents the predicted change in the $y$-variable for each unit increase in the $x$-variable. A slope of $8$ means that for each additional hour studied, the predicted test score increases by $8$ points. The claim that studying $8$ hours guarantees a score of $100$ confuses slope with a specific prediction and ignores the $y$-intercept. Interpreting $8$ as an average score confuses slope with mean. Stating the score increases by $1$ point for every $8$ hours inverts the slope relationship.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NACH1L', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'The population of a town increased from $12{,}500$ to $15{,}000$ over a five-year period. What is the percent increase in the population?', NULL, $lyceon_json$[{"key":"A","text":"$16.\\overline{6}\\%$"},{"key":"B","text":"$20\\%$"},{"key":"C","text":"$25\\%$"},{"key":"D","text":"$83.\\overline{3}\\%$"}]$lyceon_json$::jsonb, 'B', NULL, E'The increase is $15{,}000 - 12{,}500 = 2{,}500$. The percent increase is $\\frac{2{,}500}{12{,}500} \\times 100 = 20\\%$. The result $16.\\overline{6}\\%$ comes from dividing the increase by the new population ($\\frac{2{,}500}{15{,}000}$) instead of the original. The result $25\\%$ comes from dividing incorrectly, such as computing $\\frac{15{,}000}{12{,}500}$ and subtracting $1$ but using $\\frac{2{,}500}{10{,}000}$. The result $83.\\overline{3}\\%$ comes from dividing the original by the new value rather than computing the change relative to the original.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NX3OHZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A university mailed a career satisfaction survey to $5{,}000$ randomly selected alumni. Only $800$ alumni responded, and $78\\%$ of respondents reported being "very satisfied" with their careers. The university concluded that approximately $78\\%$ of all alumni are very satisfied with their careers. Which of the following is the most significant concern with this conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The original sample of $5{,}000$ alumni was not large enough to represent the entire alumni population."},{"key":"B","text":"Alumni who are more satisfied with their careers may have been more likely to respond, so the $78\\%$ figure may overestimate satisfaction among all alumni."},{"key":"C","text":"The survey should have included current students to provide a more comprehensive view of satisfaction."},{"key":"D","text":"No margin of error was reported, so the result has no statistical meaning."}]$lyceon_json$::jsonb, 'B', NULL, E'The most significant concern is nonresponse bias. Only $800$ out of $5{,}000$ selected alumni responded, a response rate of $16\\%$. Alumni who are satisfied may be more inclined to complete a career satisfaction survey, while dissatisfied alumni may ignore it. This self-selection among respondents can systematically skew the results upward. The distractor about $5{,}000$ being too small misidentifies the problem; the original random selection was large, but the low response rate undermines representativeness. The distractor about including current students is irrelevant because the claim is specifically about alumni satisfaction. The distractor about the missing margin of error identifies a real omission but not the most significant concern; even with a reported margin of error, the estimate would still be biased by differential nonresponse.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2O9ZM7L', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $\\frac{4x^2 - 16}{2x + 4}$ for all values of $x$ where the expression is defined?', NULL, $lyceon_json$[{"key":"A","text":"$2x + 4$"},{"key":"B","text":"$2x - 4$"},{"key":"C","text":"$2x - 8$"},{"key":"D","text":"$2x + 2$"}]$lyceon_json$::jsonb, 'B', NULL, E'Factor the numerator as $4(x^2 - 4) = 4(x - 2)(x + 2)$ and the denominator as $2(x + 2)$. Canceling the common factor $(x + 2)$ gives $\\frac{4(x - 2)}{2} = 2(x - 2) = 2x - 4$. The expression $2x + 4$ results from neglecting the sign change, as if the numerator factored with $(x + 2)^2$. The expression $2x - 8$ comes from incorrectly doubling the constant after cancellation. The expression $2x + 2$ results from an error in distributing $2(x - 2)$, treating $-2$ as $+1$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P3GY4D', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A water tank initially contains $200$ gallons of water. Water drains from the tank at a constant rate of $8$ gallons per minute. Which function $f(t)$ gives the amount of water, in gallons, remaining in the tank after $t$ minutes?', NULL, $lyceon_json$[{"key":"A","text":"$f(t) = 200 + 8t$"},{"key":"B","text":"$f(t) = 200 - 8t$"},{"key":"C","text":"$f(t) = 8t - 200$"},{"key":"D","text":"$f(t) = 200 - \\frac{t}{8}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $f(t) = 200 - 8t$. The tank starts with $200$ gallons and loses $8$ gallons each minute, so the remaining amount decreases linearly: $200 - 8t$. The expression $200 + 8t$ incorrectly adds water each minute rather than subtracting it. The expression $8t - 200$ reverses the initial amount and the drain term, which yields negative values for small $t$ and does not model the situation. The expression $200 - \\frac{t}{8}$ incorrectly inverts the rate, subtracting $\\frac{1}{8}$ of a gallon per minute instead of $8$ gallons per minute.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PC1ZLH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A city surveyed a random sample of $800$ residents and found that $45\\%$ support building a new library. The margin of error for the survey is $\\pm 3$ percentage points. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $45\\%$ of all city residents support building the library."},{"key":"B","text":"It is plausible that between $42\\%$ and $48\\%$ of all city residents support building the library."},{"key":"C","text":"Between $42\\%$ and $48\\%$ of the $800$ sampled residents support building the library."},{"key":"D","text":"If the survey were repeated, exactly $45\\%$ of respondents would support building the library each time."}]$lyceon_json$::jsonb, 'B', NULL, E'A margin of error of $\\pm 3$ percentage points means the plausible range for the true population proportion is $45\\% \\pm 3\\%$, or between $42\\%$ and $48\\%$. This interval estimates where the population parameter lies, not the sample statistic. The distractor stating exactly $45\\%$ ignores sampling variability and treats the sample proportion as if it were the exact population value. The distractor applying the interval to the sampled residents confuses the population parameter (which is estimated) with the sample statistic (which is already known). The distractor claiming every repeat would yield $45\\%$ misunderstands that different random samples produce different estimates.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PK1EBW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A shirt originally costs $\\$80$. It is on sale for $25\\%$ off. What is the sale price of the shirt?', NULL, $lyceon_json$[{"key":"A","text":"$\\$20$"},{"key":"B","text":"$\\$55$"},{"key":"C","text":"$\\$60$"},{"key":"D","text":"$\\$100$"}]$lyceon_json$::jsonb, 'C', NULL, E'A $25\\%$ discount on $\\$80$ is $0.25 \\times 80 = \\$20$. The sale price is $80 - 20 = \\$60$. The result $\\$20$ is just the discount amount, not the sale price. The result $\\$55$ comes from an arithmetic error in the subtraction. The result $\\$100$ incorrectly adds the discount to the original price instead of subtracting it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q8NAVP', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $g$ is defined by $g(x) = (x - 3)^2 - 4$. What is the minimum value of $g(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$-4$"},{"key":"B","text":"$-3$"},{"key":"C","text":"$3$"},{"key":"D","text":"$5$"}]$lyceon_json$::jsonb, 'A', NULL, E'The function $g(x) = (x - 3)^2 - 4$ is in vertex form $a(x - h)^2 + k$ with vertex at $(3, -4)$. Since $a = 1 > 0$, the parabola opens upward and the minimum value is $k = -4$. The value $-3$ confuses the horizontal shift with the minimum output of the function. The value $3$ is the $x$-coordinate where the minimum occurs, not the minimum output value itself. The value $5$ results from expanding incorrectly and misidentifying the constant term, or from adding $|{-4}|$ and $|3|$ minus some offset.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QE9NFG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A survey of $500$ randomly selected adults found that $58\\%$ prefer online shopping, with a margin of error of $\\pm 4.3$ percentage points. A second survey of $2{,}000$ randomly selected adults from the same population found that $55\\%$ prefer online shopping, with a margin of error of $\\pm 2.2$ percentage points. The $95\\%$ confidence intervals for the two surveys overlap. Which of the following conclusions is best supported?', NULL, $lyceon_json$[{"key":"A","text":"The first survey is unreliable because it has a larger margin of error."},{"key":"B","text":"The true proportion is exactly $55\\%$ because the second survey has a larger sample size."},{"key":"C","text":"There is no convincing evidence that the two surveys estimate different population proportions, since their confidence intervals overlap."},{"key":"D","text":"The second survey must be more accurate because larger samples always produce point estimates closer to the true value."}]$lyceon_json$::jsonb, 'C', NULL, E'Because the $95\\%$ confidence intervals from the two surveys overlap, the observed difference between $58\\%$ and $55\\%$ is within the range that could be explained by sampling variability. There is no convincing evidence that the surveys are estimating different population values. The distractor calling the first survey unreliable is incorrect because a wider margin of error reflects a smaller sample, not a flawed methodology. The distractor claiming the true value is exactly $55\\%$ treats a point estimate as if it were exact, ignoring the margin of error. The distractor about larger samples always producing closer point estimates confuses reduced variability (on average) with guaranteed accuracy for any single sample.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2R407O8', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'grid_in', E'The solution set of $3(2x - 5) + 4 \\geq 7x - 2(x + 1)$ can be written as $x \\geq k$. What is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9', ARRAY['9'], E'Distribute on the left side: $3(2x - 5) + 4 = 6x - 15 + 4 = 6x - 11$. Distribute on the right side: $7x - 2(x + 1) = 7x - 2x - 2 = 5x - 2$. The inequality becomes $6x - 11 \\geq 5x - 2$. Subtract $5x$ from both sides: $x - 11 \\geq -2$. Add $11$ to both sides: $x \\geq 9$. Therefore $k = 9$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RQIADU', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'If $a + b = 5$ and $ab = 3$, what is the value of $a^3 + b^3$?', NULL, $lyceon_json$[{"key":"A","text":"$80$"},{"key":"B","text":"$125$"},{"key":"C","text":"$110$"},{"key":"D","text":"$75$"}]$lyceon_json$::jsonb, 'A', NULL, E'Use the identity $a^3 + b^3 = (a + b)^3 - 3ab(a + b)$. Substituting gives $(5)^3 - 3(3)(5) = 125 - 45 = 80$. The value $125$ results from computing only $(a + b)^3$ without subtracting the $3ab(a + b)$ correction term. The value $110$ comes from a computational error in evaluating $3 \\times 3 \\times 5$ as $15$ instead of $45$, yielding $125 - 15 = 110$. The value $75$ results from using the wrong identity $(a + b)^2 \\cdot ab = 25 \\times 3 = 75$, confusing the sum-of-cubes formula with a product of the given quantities.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RSXD9Z', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'Two parallel lines are cut by a transversal. One of the alternate exterior angles measures $(2x + 15)^\\circ$ and the other measures $(4x - 9)^\\circ$. What is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$12$"},{"key":"C","text":"$24$"},{"key":"D","text":"$29$"}]$lyceon_json$::jsonb, 'B', NULL, E'Alternate exterior angles formed by a transversal cutting parallel lines are equal. Setting them equal: $2x + 15 = 4x - 9$. Solving: $24 = 2x$, so $x = 12$. The value $6$ results from an arithmetic slip such as dividing $24$ by $4$ instead of $2$. The value $24$ comes from finding $2x = 24$ but reporting $2x$ instead of $x$. The value $29$ results from incorrectly treating the angles as supplementary: $(2x + 15) + (4x - 9) = 180$ gives $6x + 6 = 180$, so $6x = 174$ and $x = 29$.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TRF4VR', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'grid_in', E'A swimming pool has a cross-section shaped like a trapezoid, with parallel sides of length $8$ meters and $14$ meters and a depth (height of the trapezoid) of $5$ meters. The pool extends $20$ meters in length. What is the volume of the pool, in cubic meters?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '1100', ARRAY['1100'], E'The cross-sectional area of the trapezoidal shape is $A = \\frac{1}{2}(b_1 + b_2) \\times h = \\frac{1}{2}(8 + 14) \\times 5 = \\frac{1}{2}(22)(5) = 55$ square meters. The volume of the prism is the cross-sectional area times the length: $V = 55 \\times 20 = 1100$ cubic meters. A common error is omitting the $\\frac{1}{2}$ factor in the trapezoid area formula, computing $22 \\times 5 = 110$ and then $110 \\times 20 = 2200$. Another error is using only one of the parallel sides instead of their average, such as $8 \\times 5 \\times 20 = 800$ or $14 \\times 5 \\times 20 = 1400$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UNL6QX', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $f$ is defined by $f(x) = -2(x - 3)^2 + 18$. Which of the following correctly describes the range of $f$?', NULL, $lyceon_json$[{"key":"A","text":"$f(x) \\leq 18$"},{"key":"B","text":"$f(x) \\geq 18$"},{"key":"C","text":"$f(x) \\leq 3$"},{"key":"D","text":"$f(x) \\geq -18$"}]$lyceon_json$::jsonb, 'A', NULL, E'The function $f(x) = -2(x - 3)^2 + 18$ is a downward-opening parabola (since $a = -2 < 0$) in vertex form with vertex at $(3, 18)$. Because the parabola opens downward, the vertex represents the maximum value, so $f(x) \\leq 18$ for all $x$. The claim $f(x) \\geq 18$ reverses the direction of the inequality, treating the vertex as a minimum rather than a maximum — an error that comes from ignoring the negative leading coefficient. The claim $f(x) \\leq 3$ confuses the $x$-coordinate of the vertex with the maximum output value. The claim $f(x) \\geq -18$ applies an incorrect sign to the constant term and treats it as a minimum.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VH7OG1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'grid_in', E'A chemist mixes two solutions. Solution X contains $40\\%$ acid and Solution Y contains $70\\%$ acid. She uses $3$ liters of Solution X and some amount of Solution Y to create a mixture that is $52\\%$ acid. How many liters of Solution Y does she use?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '2', ARRAY['2'], E'Let $y$ represent the number of liters of Solution Y. The total acid from Solution X is $0.40 \\times 3 = 1.2$ liters, and from Solution Y is $0.70y$ liters. The total volume of the mixture is $3 + y$ liters and must be $52\\%$ acid, so $\\frac{1.2 + 0.70y}{3 + y} = 0.52$. Multiplying both sides by $(3 + y)$ gives $1.2 + 0.70y = 1.56 + 0.52y$. Subtracting $0.52y$ from both sides gives $1.2 + 0.18y = 1.56$. Subtracting $1.2$ gives $0.18y = 0.36$, so $y = 2$. A common error is setting up the equation without accounting for the total volume changing, which would yield a different answer.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WFIJ9O', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'grid_in', E'A biologist models the relationship between temperature $t$ (in degrees Celsius) and the growth rate $g$ (in millimeters per day) of a certain plant species using the equation $g = -0.05t^2 + 2.5t - 20$. According to this model, at what temperature, in degrees Celsius, does the plant achieve its maximum growth rate?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '25', ARRAY['25'], E'The equation $g = -0.05t^2 + 2.5t - 20$ is a downward-opening parabola because the coefficient of $t^2$ is negative. The maximum occurs at the vertex, where $t = -\\frac{b}{2a} = -\\frac{2.5}{2(-0.05)} = -\\frac{2.5}{-0.1} = 25$. The maximum growth rate occurs at $25$ degrees Celsius. A common error is substituting values into the equation to find the growth rate rather than finding the temperature that maximizes it. Another error is using $\\frac{b}{2a}$ without the negative sign, yielding $-25$, which is not physically meaningful in this context.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WPQVX8', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A factory produces $240$ widgets in $8$ hours. At this constant rate, how many widgets does the factory produce in $5$ hours?', NULL, $lyceon_json$[{"key":"A","text":"$120$"},{"key":"B","text":"$150$"},{"key":"C","text":"$192$"},{"key":"D","text":"$200$"}]$lyceon_json$::jsonb, 'B', NULL, E'The factory produces $\\frac{240}{8} = 30$ widgets per hour. In $5$ hours it produces $30 \\times 5 = 150$ widgets. The result $120$ comes from halving the total instead of finding the unit rate. The result $192$ is an arithmetic error. The result $200$ comes from an incorrect setup such as dividing $8$ into groups of $5$ incorrectly.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X3FWIT', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A shelf in a bookstore contains $7$ mystery novels, $5$ science fiction novels, and $3$ biographies. If one book is selected at random from the shelf, what is the probability that it is a science fiction novel?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{1}{5}$"},{"key":"B","text":"$\\frac{5}{12}$"},{"key":"C","text":"$\\frac{1}{3}$"},{"key":"D","text":"$\\frac{7}{15}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The total number of books on the shelf is $7 + 5 + 3 = 15$. There are $5$ science fiction novels, so the probability of selecting one is $\\frac{5}{15} = \\frac{1}{3}$. The distractor $\\frac{1}{5}$ incorrectly uses the count of science fiction novels as the denominator, treating each science fiction book as equally likely to be the only option. The distractor $\\frac{5}{12}$ results from subtracting the biography count from the total and using $12$ as the denominator. The distractor $\\frac{7}{15}$ gives the probability of selecting a mystery novel rather than a science fiction novel.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XR3TOO', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'Two fair six-sided dice are rolled. Given that the sum of the two dice is at least $9$, what is the probability that at least one of the dice shows a $6$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7}{36}$"},{"key":"B","text":"$\\frac{5}{18}$"},{"key":"C","text":"$\\frac{3}{5}$"},{"key":"D","text":"$\\frac{7}{10}$"}]$lyceon_json$::jsonb, 'D', NULL, E'First, enumerate all outcomes where the sum is at least $9$. For sum $= 9$: $(3,6)$, $(4,5)$, $(5,4)$, $(6,3)$ — $4$ outcomes. For sum $= 10$: $(4,6)$, $(5,5)$, $(6,4)$ — $3$ outcomes. For sum $= 11$: $(5,6)$, $(6,5)$ — $2$ outcomes. For sum $= 12$: $(6,6)$ — $1$ outcome. The total is $10$ outcomes. Among these $10$, the outcomes with at least one $6$ are $(3,6)$, $(6,3)$, $(4,6)$, $(6,4)$, $(5,6)$, $(6,5)$, $(6,6)$ — $7$ outcomes. So the conditional probability is $\\frac{7}{10}$. The distractor $\\frac{7}{36}$ divides $7$ by the full sample space of $36$ instead of conditioning on the sum being at least $9$. The distractor $\\frac{5}{18}$ equals $\\frac{10}{36}$, which is the probability that the sum is at least $9$ without any further condition. The distractor $\\frac{3}{5}$ results from miscounting the favorable outcomes as $6$ instead of $7$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YDB033', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $f(x) = 3x + 7$ models the total cost, in dollars, of renting a bicycle for $x$ hours. What does the number $3$ represent in this context?', NULL, $lyceon_json$[{"key":"A","text":"The initial rental fee, in dollars"},{"key":"B","text":"The total cost of renting a bicycle for $1$ hour"},{"key":"C","text":"The additional cost, in dollars, for each additional hour of rental"},{"key":"D","text":"The number of hours the bicycle can be rented"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is that $3$ represents the additional cost, in dollars, for each additional hour of rental. In the function $f(x) = 3x + 7$, the coefficient $3$ is the rate of change, meaning the cost increases by $\\$3$ for each additional hour. The initial rental fee is represented by the constant term $7$, not by the coefficient of $x$. The total cost for $1$ hour would be $f(1) = 3(1) + 7 = 10$, which is not the same as $3$. The number of hours rented is represented by $x$, the input variable.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z3TJ3D', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, the two legs have lengths $5$ and $12$. What is the length of the hypotenuse?', NULL, $lyceon_json$[{"key":"A","text":"$11$"},{"key":"B","text":"$13$"},{"key":"C","text":"$17$"},{"key":"D","text":"$\\sqrt{119}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Using the Pythagorean theorem: $c^2 = 5^2 + 12^2 = 25 + 144 = 169$, so $c = 13$. The value $11$ results from an arithmetic slip such as miscalculating $\\sqrt{169}$. The value $17$ comes from adding the legs directly ($5 + 12 = 17$) instead of using the Pythagorean theorem. The value $\\sqrt{119}$ results from subtracting the squares ($144 - 25 = 119$), as if one of the given lengths were the hypotenuse rather than a leg.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21YL6BX', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Linguist Noam Chomsky proposed that humans possess an innate capacity for language acquisition. Many cognitive scientists have embraced this ______ some researchers in the field of developmental psychology argue that language emerges primarily through social interaction rather than from any inborn mechanism.', $lyceon_json$[{"key":"A","text":"idea, however,"},{"key":"B","text":"idea; however,"},{"key":"C","text":"idea however"},{"key":"D","text":"idea, however;"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct choice uses a semicolon before ''however'' and a comma after it. Two independent clauses joined by a conjunctive adverb such as ''however'' require a semicolon between the clauses and a comma after the adverb. Using only commas around ''however'' creates a comma splice, because the comma before ''however'' is not strong enough to separate two independent clauses. Omitting all punctuation around ''however'' fuses the two clauses and removes the necessary pause after the transitional word. Placing a comma before ''however'' and a semicolon after it reverses the required punctuation pattern: the stronger mark must come between the independent clauses, not after the adverb.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW220XP87', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'A historian argues that the construction of transcontinental railroads in the nineteenth century fundamentally altered the economic geography of the United States. Which finding, if true, would most directly support this argument?', E'Before the completion of the First Transcontinental Railroad in 1869, transporting goods from the East Coast to the West Coast of the United States required either a months-long overland journey by wagon or a sea voyage around the southern tip of South America. The railroad reduced this transit time to approximately one week. Economists have noted that regions along new rail corridors experienced rapid population growth and industrial development, while previously thriving trade hubs that were bypassed by rail lines often stagnated. Some scholars have also examined how standardized rail schedules necessitated the adoption of uniform time zones across the country, replacing the patchwork of local solar times that had previously prevailed.', $lyceon_json$[{"key":"A","text":"Towns located along transcontinental rail lines saw manufacturing output increase by an average of 300 percent within a decade, while towns more than fifty miles from any rail line showed no comparable growth."},{"key":"B","text":"The construction of the railroad employed tens of thousands of immigrant laborers, many of whom faced dangerous working conditions."},{"key":"C","text":"Several prominent politicians of the era opposed railroad construction on the grounds that it would benefit private corporations at public expense."},{"key":"D","text":"Railroad companies often printed elaborate promotional posters to attract settlers to western territories."}]$lyceon_json$::jsonb, 'A', NULL, E'The finding that towns along rail lines experienced a 300 percent increase in manufacturing output while distant towns showed no comparable growth directly demonstrates that railroads reshaped the geographic distribution of economic activity, supporting the historian''s argument. The finding about immigrant laborers and dangerous conditions addresses labor history and social consequences, not economic geography. The finding about political opposition concerns the debate over railroad policy rather than the railroad''s actual effects on economic patterns. The finding about promotional posters relates to marketing strategies, not to measurable changes in economic geography.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW224QQUQ', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Honeybees communicate the location of food sources through a behavior known as the waggle dance. When a forager bee returns to the hive after discovering a productive flower patch, it performs a figure-eight movement on the honeycomb surface. The angle of the dance relative to vertical indicates the direction of the food source in relation to the sun, while the duration of the waggle portion signals the distance. Other bees observe the dance closely and then fly to the indicated location with remarkable accuracy.', $lyceon_json$[{"key":"A","text":"Honeybees use a structured dance to convey precise directional and distance information about food sources to other members of the hive."},{"key":"B","text":"Honeybees are the only insect species capable of communicating spatial information to one another."},{"key":"C","text":"The waggle dance is performed primarily to establish dominance within the social hierarchy of the hive."},{"key":"D","text":"Scientists have struggled to decode the meaning of honeybee dances because the movements appear random."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes how honeybees use the waggle dance to communicate both direction and distance of food sources, making the choice about conveying precise directional and distance information the best summary. The claim that honeybees are the only insect species capable of spatial communication goes beyond anything the passage states; no comparison with other species is made. The claim about establishing dominance misreads the purpose of the dance, which the passage explicitly links to food-source communication, not social hierarchy. The claim that scientists have struggled to decode the dance contradicts the passage, which describes the dance''s meaning as well understood.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2255J2X', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'In the early twentieth century, the boll weevil devastated cotton crops across the American South, forcing many farmers into economic ruin. _______ the destruction ultimately prompted a dramatic agricultural shift: farmers in regions like Coffee County, Alabama, diversified into peanuts, soybeans, and other crops, eventually achieving greater prosperity than they had known under cotton monoculture.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"Paradoxically,"},{"key":"C","text":"For example,"},{"key":"D","text":"In summary,"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct transition is "Paradoxically," because the second sentence presents an outcome that seems contradictory to what would be expected from the devastation described in the first sentence: a destructive pest ultimately led to greater economic prosperity. This surprising reversal is precisely what "paradoxically" signals. "Furthermore" merely adds information and fails to capture the unexpected nature of the outcome. "For example" treats the agricultural shift as an illustration of economic ruin, when the passage actually describes the shift as leading to recovery and greater prosperity. "In summary" implies the second sentence condenses information already stated, but it introduces entirely new developments not mentioned in the first sentence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22ASEGA', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'While writing a report about pollinator conservation, a student wants to highlight the primary threat facing monarch butterfly populations. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22HRV0N', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'In a 2018 paper on cognitive development, psychologist Renata Bowen challenged the prevailing view that childhood creativity declines uniformly as children enter formal schooling. Bowen''s longitudinal study tracked 400 students from ages five to twelve and found that while conventional test scores for creative thinking did drop, children who received open-ended art instruction maintained their imaginative output. Bowen concluded that the apparent decline is not ______ but is instead a product of educational environments that prioritize convergent thinking.', $lyceon_json$[{"key":"A","text":"inevitable"},{"key":"B","text":"imaginary"},{"key":"C","text":"intentional"},{"key":"D","text":"permanent"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is "inevitable." Bowen argues that the decline in creativity is not a necessary or unavoidable outcome, since children who received art instruction did not experience the decline — the word "inevitable" means certain to happen and impossible to prevent, which is precisely what Bowen''s findings contradict. "Imaginary" means existing only in the imagination or not real, but Bowen acknowledges that the decline does occur in most settings; she disputes its inevitability, not its existence. "Intentional" means done deliberately or on purpose, but the passage frames the decline as a byproduct of educational environments, not as something anyone questions the deliberateness of. "Permanent" means lasting forever, but Bowen''s argument is about whether the decline can be prevented from occurring at all, not about whether it can be reversed once it has occurred.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23SFOPR', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'For decades, economists assumed that individuals make financial decisions by rationally calculating costs and benefits. Beginning in the 1970s, however, psychologists Daniel Kahneman and Amos Tversky demonstrated through a series of experiments that people systematically deviate from rational models. They found, for example, that individuals feel the pain of a financial loss roughly twice as intensely as they feel the pleasure of an equivalent gain—a phenomenon Kahneman and Tversky called loss aversion. Their work helped establish the field of behavioral economics, which integrates psychological insights into economic theory to explain why people often make choices that classical models cannot predict.', $lyceon_json$[{"key":"A","text":"Loss aversion is a cognitive bias that makes people unwilling to invest money in any situation that involves risk."},{"key":"B","text":"Research by Kahneman and Tversky revealed systematic departures from rational decision-making, giving rise to behavioral economics."},{"key":"C","text":"Classical economic models remain more accurate than behavioral economics in predicting consumer behavior."},{"key":"D","text":"Kahneman and Tversky proved that all financial decisions are driven by emotions rather than rational thought."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage traces how Kahneman and Tversky''s experiments revealed systematic deviations from rational economic models, leading to the creation of behavioral economics. The choice about their research revealing systematic departures and giving rise to behavioral economics captures this trajectory. The claim that loss aversion makes people unwilling to invest in any risky situation overgeneralizes a specific finding; the passage defines loss aversion as asymmetric sensitivity to gains and losses, not as total risk avoidance. The claim that classical models remain more accurate contradicts the passage''s point that behavioral economics was developed precisely because classical models failed to predict certain choices. The claim that all financial decisions are driven by emotions overstates the findings; the passage says people systematically deviate from rational models, not that rationality plays no role at all.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24T4EAQ', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'Throughout the twentieth century, art historians treated the paintings of self-taught artist Horace Pippin as primarily autobiographical, interpreting his wartime scenes as straightforward depictions of his combat experience in World War I. Art historian Judith Wilson challenged this reading in the 1990s, arguing that Pippin deliberately constructed his compositions using formal strategies — including symmetrical framing and muted palettes — borrowed from European academic painting traditions. Wilson contended that treating Pippin''s work as naive personal testimony ignored the sophisticated artistic decisions embedded in each canvas.', $lyceon_json$[{"key":"A","text":"It describes a long-held interpretation of an artist's work and then presents a scholar's argument that reframes that interpretation."},{"key":"B","text":"It compares the artistic techniques of two different painters from different historical periods."},{"key":"C","text":"It outlines the stages of an artist's career in chronological order from early to late works."},{"key":"D","text":"It summarizes a scholarly debate and then proposes a compromise position that reconciles both sides."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating the text describes a long-held interpretation and then presents a scholar''s argument that reframes it. The passage first explains the traditional autobiographical reading of Pippin''s art and then introduces Wilson''s contrasting argument about Pippin''s formal sophistication. The choice about comparing two painters'' techniques is wrong because the passage discusses only one painter, Pippin, and Wilson is a historian analyzing his work, not a second painter being compared. The choice about outlining career stages chronologically is wrong because the passage contrasts interpretive frameworks rather than tracing a progression of works over time. The choice about proposing a compromise is wrong because the passage presents Wilson''s view as a direct challenge to the traditional reading, not as a middle-ground synthesis.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW260ZGL5', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'The human gut microbiome—the trillions of microorganisms residing in the digestive tract—has attracted intense scientific interest in recent years. Studies have linked gut microbial composition to conditions as varied as obesity, depression, and autoimmune disease, prompting some researchers to characterize the microbiome as a previously unrecognized organ. Yet the causal mechanisms behind these associations remain poorly understood. Most studies are correlational: they show that patients with a given condition tend to have different gut bacteria than healthy controls, but they cannot determine whether the microbial differences cause the condition, result from it, or merely coincide with it. A smaller body of research using germ-free animal models has demonstrated causal effects in controlled settings, but translating these findings to humans is complicated by the microbiome''s extraordinary complexity and variability across individuals.', $lyceon_json$[{"key":"A","text":"While research has established numerous associations between gut microbiome composition and human health conditions, the causal relationships underlying those associations remain largely unresolved."},{"key":"B","text":"The gut microbiome functions as a distinct organ that directly causes obesity, depression, and autoimmune disease when its composition is disrupted."},{"key":"C","text":"Animal models have conclusively demonstrated that gut bacteria cause specific diseases in humans, confirming earlier correlational studies."},{"key":"D","text":"Scientists have lost confidence in microbiome research because most studies rely on correlational data rather than controlled experiments."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes extensive correlational evidence linking gut microbiome composition to various health conditions while emphasizing that causal mechanisms remain poorly understood. The choice about associations being established but causal relationships remaining unresolved captures both elements of this central tension. The claim that the microbiome directly causes specific diseases conflates the associations the passage describes with proven causation, which the passage explicitly states has not been established. The claim that animal models have conclusively demonstrated causation in humans misrepresents the passage, which notes that translating animal findings to humans is complicated by microbiome complexity and individual variability. The claim that scientists have lost confidence overstates the passage''s nuance; the text describes ongoing interest and active research rather than diminished confidence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW274TGS2', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Linguists have observed that pidgin languages — simplified communication systems that arise when speakers of different languages need to interact — tend to have limited grammatical structures and small vocabularies. When children grow up speaking a pidgin as their primary language, however, they spontaneously expand its grammar, adding tense markers, subordinate clauses, and systematic word-order rules. _______ what begins as a makeshift contact language is transformed within a single generation into a creole: a fully complex natural language with the expressive power of any other human tongue.', $lyceon_json$[{"key":"A","text":"In other words,"},{"key":"B","text":"Granted,"},{"key":"C","text":"Similarly,"},{"key":"D","text":"On the contrary,"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct transition is "In other words," because the third sentence restates the process described in the second sentence in more general, summarizing terms: children''s grammatical expansions result in a pidgin becoming a creole with full expressive power. The third sentence is a reformulation, not new information. "Granted" signals a concession, implying the writer is temporarily accepting a counterpoint before arguing against it, but the third sentence reinforces rather than concedes anything. "Similarly" indicates a parallel comparison to a different situation, yet the third sentence describes the same phenomenon as the second, not an analogous one. "On the contrary" signals direct contradiction, but the third sentence agrees with and restates the second rather than opposing it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27V6W18', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Glass is often perceived as a purely modern building material, but archaeological evidence shows that the ancient Romans manufactured glass windowpanes as early as the first century CE. These early panes were thick, translucent rather than transparent, and affordable only to the wealthy. It was not until the development of the crown glass technique in medieval Europe that windows became thin enough to allow clear vision. Given this long history of innovation, ________', $lyceon_json$[{"key":"A","text":"the use of glass in windows is the product of centuries of gradual technological refinement rather than a single modern invention."},{"key":"B","text":"ancient Roman glassmakers were more skilled than their medieval European successors."},{"key":"C","text":"modern glass is chemically identical to the glass produced by Roman manufacturers."},{"key":"D","text":"the crown glass technique was developed in the first century CE by Roman artisans."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage traces glass window production from ancient Rome through medieval Europe to the present, describing successive improvements. The logical completion is that glass in windows resulted from centuries of gradual refinement, not a single modern invention, which aligns with the phrase "long history of innovation." The claim that Roman glassmakers were more skilled than medieval ones contradicts the passage''s implication that the crown glass technique was an advance over earlier methods. The claim about chemical identity introduces a comparison the passage never makes. The claim that crown glass was developed in the first century misreads the timeline; the passage places this technique in medieval Europe, not ancient Rome.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28NCH8N', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'A musicologist contends that composer Clara Schumann''s editorial decisions in publishing her husband Robert Schumann''s posthumous works reflected her own artistic judgment rather than a purely faithful reproduction of his intentions. Which quotation from the text would most directly support this contention?', E'After Robert Schumann''s death in 1856, Clara Schumann devoted decades to editing and publishing his unpublished manuscripts. She approached this task with a complex mixture of reverence and independence. In her diary, she wrote that she considered it her duty to present Robert''s music "in its most perfect form," a phrase scholars have interpreted as granting herself license to alter passages she deemed unfinished or flawed. She transposed certain piano passages into different keys, adjusted dynamic markings, and in at least two cases omitted entire movements she felt were inconsistent with the rest of the composition. Correspondence with the publisher Breitkopf & Härtel reveals that she rejected their suggestion to include all extant material, insisting instead that "only what is worthy of his name should reach the public." Modern critical editions have since restored much of the material Clara excluded, prompting renewed debate about the boundary between editorial stewardship and creative intervention.', $lyceon_json$[{"key":"A","text":"\"She approached this task with a complex mixture of reverence and independence.\""},{"key":"B","text":"\"Modern critical editions have since restored much of the material Clara excluded, prompting renewed debate about the boundary between editorial stewardship and creative intervention.\""},{"key":"C","text":"\"She transposed certain piano passages into different keys, adjusted dynamic markings, and in at least two cases omitted entire movements she felt were inconsistent with the rest of the composition.\""},{"key":"D","text":"\"In her diary, she wrote that she considered it her duty to present Robert's music 'in its most perfect form.'\""}]$lyceon_json$::jsonb, 'C', NULL, E'The quotation about transposing passages, adjusting dynamic markings, and omitting entire movements provides the most direct evidence of Clara Schumann exercising her own artistic judgment. These are concrete alterations that go beyond faithful transcription, demonstrating creative editorial decisions. The description of her approach as a mixture of reverence and independence characterizes her attitude in general terms but does not cite specific editorial actions that would demonstrate artistic judgment over faithful reproduction. The quotation about modern critical editions restoring excluded material describes later scholars'' responses, not Clara''s own editorial decisions. The diary entry about presenting Robert''s music in its most perfect form reveals her stated rationale but is ambiguous: the phrase could support either faithful reproduction or independent judgment, making it less direct than the concrete examples of transposition and omission.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AMAJYA', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2APUW5U', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'By the time anthropologist Margaret Mead published her controversial study Coming of Age in Samoa in 1928, she ______ several months living among Samoan adolescents and observing their social customs. Her findings challenged prevailing Western assumptions about the universality of adolescent psychological turmoil.', $lyceon_json$[{"key":"A","text":"spent"},{"key":"B","text":"has spent"},{"key":"C","text":"had spent"},{"key":"D","text":"would spend"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct choice uses the past perfect ''had spent'' because the action of spending months in Samoa was completed before the past-tense event of publishing the study in 1928. The construction ''By the time...published'' establishes a past reference point and requires the past perfect to indicate the earlier of two past actions. The simple past ''spent'' fails to establish the correct temporal sequence, leaving the two events without a clear before-and-after relationship. The present perfect ''has spent'' is anchored to the present moment, which conflicts with the passage''s entirely past-tense narrative. The conditional ''would spend'' implies a hypothetical or future-in-the-past action, suggesting the time had not yet been spent, which contradicts the meaning of the sentence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
