INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BWMESI', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'During the California Gold Rush, thousands of prospectors arrived in San Francisco hoping to strike it rich. Many discovered, however, that mining was backbreaking labor with uncertain rewards. Merchants who sold tools, clothing, and provisions to the miners often earned far more reliable profits than the miners themselves, leading some historians to describe these sellers as the true ______ of the Gold Rush era.', $lyceon_json$[{"key":"A","text":"beneficiaries"},{"key":"B","text":"spectators"},{"key":"C","text":"casualties"},{"key":"D","text":"architects"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is "beneficiaries." The passage states that merchants earned reliable profits, making them the people who gained the most advantage — the definition of beneficiaries. "Spectators" means passive onlookers, but the merchants were active participants earning profits, not merely watching. "Casualties" means victims who suffer harm or loss, the opposite of gaining profits. "Architects" means designers or planners of something, but the passage describes merchants who profited from the Gold Rush, not people who designed or orchestrated it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2C635AL', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Sociologist Erving Goffman proposed that everyday social interactions resemble theatrical performances in which individuals present carefully managed versions of themselves to different audiences. A job applicant, for example, may emphasize competence and enthusiasm in an interview while downplaying personal anxieties. Goffman called this process "impression management" and argued that it is not inherently deceptive but rather a fundamental mechanism through which social order is maintained. Critics, however, have questioned whether Goffman''s framework applies equally well to digital communication, where visual and vocal cues are absent and individuals can craft responses with far more deliberation than face-to-face encounters allow. These critics suggest that ________', $lyceon_json$[{"key":"A","text":"digital communication may involve a qualitatively different form of impression management than the spontaneous performances Goffman originally described."},{"key":"B","text":"Goffman's theory of impression management has been entirely discredited by the rise of social media and digital communication."},{"key":"C","text":"people are more honest in digital communication because they have additional time to reflect before responding."},{"key":"D","text":"face-to-face interaction no longer plays a significant role in maintaining social order in contemporary society."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents critics who question whether Goffman''s framework applies equally well to digital communication, noting key differences such as absent visual cues and greater deliberation time. The logical completion is that digital communication involves a qualitatively different form of impression management, which follows naturally from the critics'' concerns. The claim that Goffman''s theory has been entirely discredited overstates the criticism; the critics question its applicability to a new medium, not the framework''s validity overall. The claim that people are more honest digitally misinterprets the additional deliberation time, which the passage frames as enabling more managed self-presentation, not greater honesty. The claim that face-to-face interaction no longer matters extends far beyond the critics'' point, which concerns the differences between media, not the irrelevance of in-person interaction.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CH26AY', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Restoration ecologists working to revive degraded prairies have long relied on seed mixes composed of native grass and wildflower species historically present in the target ecosystem. Recent research, however, has complicated this approach. Genetic analyses reveal that commercially available native seed stocks often originate from populations hundreds of miles from the restoration site, raising concerns about local adaptation: plants grown from distant seed sources may be poorly suited to local soil chemistry, precipitation patterns, and pollinator communities. At the same time, sourcing seed exclusively from nearby remnant prairies risks depleting those already fragile populations. Balancing these competing pressures, some ecologists now advocate a strategy called "admixture provenancing," which blends seed from multiple source populations across a species'' range to maximize genetic diversity. Critics of this approach warn that introducing distant genotypes could disrupt co-adapted gene complexes refined over millennia of local selection. The debate thus illustrates that ________', $lyceon_json$[{"key":"A","text":"efforts to restore degraded ecosystems must navigate tensions between genetic diversity and local adaptation, with no current consensus on how best to reconcile the two."},{"key":"B","text":"commercially available seed stocks are always genetically inferior to seed collected directly from remnant prairies near the restoration site."},{"key":"C","text":"admixture provenancing has been proven to produce healthier prairie restorations than any single-source seeding strategy."},{"key":"D","text":"restoration ecology is an impractical field because the genetic risks of any seeding strategy inevitably outweigh the ecological benefits of restoration."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents a tension between maximizing genetic diversity through admixture provenancing and preserving locally adapted gene complexes, with proponents and critics on each side and no resolution offered. The logical completion is that restoration must navigate these tensions without current consensus on reconciliation. The claim that commercial seed stocks are always genetically inferior overstates the concern: the passage raises questions about local adaptation, not blanket inferiority, and notes that local sourcing carries its own risk of depleting remnant populations. The claim that admixture provenancing has been proven superior contradicts the passage, which presents the strategy as advocated by some ecologists but challenged by critics who warn of disrupting co-adapted gene complexes. The claim that restoration ecology is impractical because genetic risks inevitably outweigh benefits goes far beyond the passage''s scope; the text presents an active scientific debate, not a verdict against the entire field.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DVIZPW', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Based on the texts, how does the position presented in Text 2 relate to the position presented in Text 1?', E'Text 1:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ESUZZ6', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Marine biologist Sylvia Earle has spent decades advocating for ocean conservation. In a 2019 lecture at the Smithsonian ______ she urged governments to designate at least thirty percent of the world''s oceans as protected areas by 2030.', $lyceon_json$[{"key":"A","text":"Institution,"},{"key":"B","text":"Institution;"},{"key":"C","text":"Institution"},{"key":"D","text":"Institution:"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice places a comma after ''Institution'' to separate the introductory prepositional phrase ''In a 2019 lecture at the Smithsonian Institution'' from the main clause ''she urged governments.'' A comma is the standard punctuation for setting off a long introductory phrase from the independent clause that follows. A semicolon is incorrect because it is used to join two independent clauses, and an introductory prepositional phrase is not an independent clause. Omitting punctuation entirely makes the sentence harder to parse by running the introductory phrase directly into the main clause. A colon would be inappropriate because the introductory phrase is not an independent clause that introduces what follows.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FFSTH2', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'While preparing a presentation for a history class, a student wants to argue that the construction of the Panama Canal required solving a public health crisis, not just an engineering challenge. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FM5OV2', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text?', E'Honeybees communicate the location of food sources through a behavior known as the waggle dance. A forager bee that has found nectar returns to the hive and performs a series of movements on the honeycomb surface. <u>The angle of the dance relative to the vertical indicates the direction of the food source relative to the sun, and the duration of the waggle phase indicates the distance.</u> Other bees observe the dance and then fly to the indicated location to collect nectar.', $lyceon_json$[{"key":"A","text":"It explains the specific information conveyed by the components of the behavior introduced in the preceding sentences."},{"key":"B","text":"It questions whether the waggle dance is an effective method of communication among bees."},{"key":"C","text":"It describes the evolutionary origins of the waggle dance behavior in honeybee colonies."},{"key":"D","text":"It contrasts the waggle dance with other forms of animal communication."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating the sentence explains the specific information conveyed by the components of the behavior. The underlined sentence details what the angle and duration of the dance communicate — direction and distance — thereby elaborating on the waggle dance introduced in the previous sentences. The choice suggesting the sentence questions the dance''s effectiveness is wrong because the sentence presents factual information about how the dance encodes location data, with no evaluative or skeptical framing. The choice about evolutionary origins is wrong because the sentence describes how the dance works mechanically, not how it evolved. The choice about contrasting the dance with other animal communication is wrong because no other species or communication method is mentioned.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HR3VE7', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Galápagos tortoise is one of the longest-lived vertebrates on Earth. Each of the fourteen recognized subspecies ______ distinct physical characteristics shaped by the specific island environment in which it evolved.', $lyceon_json$[{"key":"A","text":"display"},{"key":"B","text":"displaying"},{"key":"C","text":"displays"},{"key":"D","text":"have displayed"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct choice uses the singular verb ''displays'' to agree with the singular subject ''Each.'' The pronoun ''Each'' is always singular, even when followed by a prepositional phrase containing a plural noun such as ''subspecies.'' The plural verb ''display'' incorrectly treats the nearby plural noun ''subspecies'' as the subject. The participle ''displaying'' does not function as a finite verb and produces a sentence fragment lacking a main verb. The plural form ''have displayed'' also fails to agree with the singular ''Each'' and introduces a present perfect tense that is not supported by the passage''s use of the simple present.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JA2VJB', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the overall purpose of the text?', E'Economist Yael Tamir has argued that the rise of meritocratic ideology in Western democracies has paradoxically deepened social divisions. In a system that rewards individual talent and effort, those who succeed come to view their advantages as earned and deserved, while those who struggle are implicitly judged as lacking ability or discipline. Tamir observes that this dynamic erodes the solidarity that sustained earlier welfare-state models, in which economic misfortune was understood as a shared risk rather than a personal failing. She does not advocate abandoning merit-based systems entirely but contends that without deliberate institutional mechanisms to maintain mutual obligation, meritocracies generate a "hubris of the successful" that corrodes democratic culture.', $lyceon_json$[{"key":"A","text":"To detail the historical sequence of policy changes that led Western democracies to adopt meritocratic systems."},{"key":"B","text":"To present a scholar's analysis of how a widely endorsed social framework can produce unintended consequences for democratic cohesion."},{"key":"C","text":"To argue that welfare-state models are economically superior to merit-based systems in all circumstances."},{"key":"D","text":"To contrast two economists who hold opposing views on whether individual talent determines economic outcomes."}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is the choice stating the text presents a scholar''s analysis of how a widely endorsed framework produces unintended consequences for democratic cohesion. The passage explains Tamir''s argument that meritocracy, while broadly accepted, paradoxically undermines solidarity and democratic culture — an analysis of unintended effects. The choice about detailing a historical sequence of policy changes is wrong because the passage discusses the psychological and social effects of meritocratic ideology, not a chronological account of policy adoption. The choice claiming the text argues welfare-state models are universally superior is wrong because Tamir explicitly does not advocate abandoning merit-based systems; she calls for institutional mechanisms to mitigate their effects. The choice about contrasting two economists is wrong because only Tamir''s perspective is presented; no opposing economist appears in the passage.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JRJQUJ', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'While drafting an essay for a science publication, a student wants to convey that a recent discovery about tardigrades challenges a widely held assumption while noting that the finding has not yet been replicated. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KW4ABU', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The James Webb Space Telescope has captured images of galaxies that formed within a few hundred million years of the Big Bang. These ancient ______ are forcing astrophysicists to reconsider models of early galaxy formation that had been widely accepted for decades.', $lyceon_json$[{"key":"A","text":"galaxies, which appear far more structured than scientists predicted,"},{"key":"B","text":"galaxies, which appear far more structured than scientists predicted"},{"key":"C","text":"galaxies which appear far more structured than scientists predicted,"},{"key":"D","text":"galaxies which appear far more structured than scientists predicted"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice sets off the nonrestrictive clause ''which appear far more structured than scientists predicted'' with commas on both sides. The clause is nonrestrictive because ''These ancient galaxies'' already identifies which galaxies are being discussed; the ''which'' clause adds supplementary information rather than defining the noun. A nonrestrictive clause must be enclosed by matching commas. Placing a comma only before the clause but omitting the closing comma leaves the parenthetical boundary unclosed, disrupting the sentence structure. Omitting the opening comma but including the closing one reverses the error, creating an asymmetric boundary. Omitting both commas treats the clause as restrictive, implying that only some of the ancient galaxies appear more structured than predicted, which contradicts the passage''s use of ''These ancient galaxies'' to refer to all of them.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2L42BOK', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Urban planners in Copenhagen have long promoted cycling infrastructure as a way to reduce traffic congestion and carbon emissions. By 2023, over 60% of the city''s residents commuted by bicycle, and studies confirmed measurable reductions in both air pollution and average commute times. _______ several outer suburbs that received the same infrastructure investments saw cycling adoption rates plateau at around 15%, leading researchers to conclude that infrastructure alone cannot overcome the longer distances and dispersed destinations characteristic of suburban commuting patterns.', $lyceon_json$[{"key":"A","text":"Additionally,"},{"key":"B","text":"Consequently,"},{"key":"C","text":"Even so,"},{"key":"D","text":"In fact,"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct transition is "Even so," because the third sentence introduces an unexpected limitation to the success story presented in the first two sentences. Despite the demonstrated effectiveness of cycling infrastructure in central Copenhagen, the same approach yielded much lower adoption in the suburbs. "Even so" captures this concessive relationship: the infrastructure worked in one context but not another. "Additionally" merely adds a parallel point and fails to signal the tension between urban success and suburban underperformance. "Consequently" implies that the suburban plateau was a direct result of the urban success, which the passage does not support. "In fact" suggests the third sentence intensifies or confirms the previous claim, when it actually qualifies and limits it by showing that the positive results did not extend to the suburbs.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2O7VOZT', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The architects tasked with redesigning the city''s central library faced a fundamental challenge ______ they had to preserve the building''s historic facade while creating a modern, energy-efficient interior that could accommodate digital resources and collaborative workspaces.', $lyceon_json$[{"key":"A","text":"challenge,"},{"key":"B","text":"challenge:"},{"key":"C","text":"challenge;"},{"key":"D","text":"challenge"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct choice places a colon after ''challenge'' because the clause that follows directly explains or specifies what the fundamental challenge was. A colon is appropriate when an independent clause introduces an explanation, and the sentence before the blank (''The architects tasked with redesigning the city''s central library faced a fundamental challenge'') is a complete independent clause. A comma after ''challenge'' creates a comma splice, joining two independent clauses with only a comma and no coordinating conjunction. A semicolon, while capable of joining two independent clauses, does not signal that the second clause is an explanation of the first, making the relationship between the clauses less clear than the colon does. Omitting punctuation entirely fuses two independent clauses into a run-on sentence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OD80OT', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'A biologist claims that certain deep-sea fish have evolved specialized adaptations for surviving in extreme pressure environments. Which finding from the text, if true, would most directly support this claim?', E'The hadal zone, located at ocean depths below 6,000 meters, is characterized by crushing pressures exceeding 600 atmospheres and near-freezing temperatures. Despite these conditions, researchers using deep-sea submersibles have observed several fish species thriving at these depths. The Mariana snailfish, discovered in the Mariana Trench at approximately 8,000 meters, has a skeleton composed largely of cartilage rather than bone, and its cells contain unusually high concentrations of trimethylamine N-oxide (TMAO), a compound that stabilizes proteins against pressure-induced deformation. Laboratory analyses have confirmed that TMAO concentrations increase proportionally with the depth at which a species is found.', $lyceon_json$[{"key":"A","text":"The Mariana snailfish's cartilaginous skeleton and elevated TMAO concentrations allow its body to maintain structural and biochemical integrity under pressures that would destroy rigid-boned fish."},{"key":"B","text":"Deep-sea submersibles have become more affordable in recent years, enabling more frequent expeditions to the hadal zone."},{"key":"C","text":"The Mariana Trench is the deepest known point in the world's oceans, reaching nearly 11,000 meters."},{"key":"D","text":"Some deep-sea fish species are bioluminescent, producing light through chemical reactions in specialized organs."}]$lyceon_json$::jsonb, 'A', NULL, E'The finding about the snailfish''s cartilaginous skeleton and elevated TMAO concentrations maintaining structural and biochemical integrity under extreme pressure directly demonstrates specialized adaptations for surviving high-pressure environments. The finding about submersible affordability concerns research technology, not fish biology or adaptation. The finding about the Mariana Trench''s depth provides geographic context but says nothing about whether fish have evolved adaptations to that environment. The finding about bioluminescence describes a different adaptation unrelated to pressure survival.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PIT479', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Elephants are known to communicate over long distances using low-frequency vocalizations called infrasound. _______ these rumbles can travel through the ground for several miles, allowing elephants to detect messages from distant herd members through vibrations in their feet.', $lyceon_json$[{"key":"A","text":"Specifically,"},{"key":"B","text":"On the other hand,"},{"key":"C","text":"Nonetheless,"},{"key":"D","text":"Previously,"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct transition is "Specifically," because the second sentence elaborates on the general claim in the first sentence by providing a concrete detail about how infrasound communication works — namely, that rumbles travel through the ground and are detected via foot vibrations. "On the other hand" incorrectly signals a contrast between the two sentences, when the second sentence actually expands on the first. "Nonetheless" implies a concession or unexpected outcome, but the second sentence logically extends the first rather than contradicting it. "Previously" suggests a temporal shift to an earlier time period, which is not supported by the passage''s content.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RQQ207', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'A team of chemists at the University of Cambridge has developed a method for synthesizing a high-strength polymer from agricultural waste. ______ the researchers demonstrated that the new material can withstand temperatures exceeding 300 degrees Celsius without degrading.', $lyceon_json$[{"key":"A","text":"Testing the polymer under extreme conditions,"},{"key":"B","text":"Having tested the polymer under extreme conditions,"},{"key":"C","text":"To test the polymer under extreme conditions,"},{"key":"D","text":"The polymer being tested under extreme conditions,"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice uses the present participle phrase ''Testing the polymer under extreme conditions'' as an introductory modifier whose implied subject matches the explicit subject of the main clause, ''the researchers.'' The testing and demonstrating happen simultaneously: in the act of testing, the researchers demonstrated the result. The perfect participle ''Having tested'' implies the testing was completed before the demonstrating, but the sentence describes the demonstration as occurring through the testing process itself, not after it concluded. The infinitive phrase ''To test'' incorrectly suggests purpose, implying that the researchers demonstrated the result in order to test the polymer, which reverses the logical relationship. The construction ''The polymer being tested'' introduces a dangling modifier because its subject, ''The polymer,'' does not match the main clause''s subject, ''the researchers.''', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2U449LN', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'Philosopher Tomoko Ishida''s 2021 book on collective memory argues that societies do not passively inherit historical narratives but actively reconstruct them to serve present needs. Ishida points to how postwar Japan selectively emphasized certain wartime experiences while marginalizing others, producing a national memory that, rather than faithfully recording the past, functioned as a ______ through which contemporary political identities were shaped and legitimized.', $lyceon_json$[{"key":"A","text":"relic"},{"key":"B","text":"chronicle"},{"key":"C","text":"vessel"},{"key":"D","text":"apparatus"}]$lyceon_json$::jsonb, 'D', NULL, E'The correct answer is "apparatus." The passage describes national memory as an active mechanism that shapes and legitimizes political identities — a functional instrument or system, which is the meaning of apparatus. "Relic" means a surviving object from an earlier era, implying passive preservation, but the passage emphasizes active reconstruction rather than mere survival from the past. "Chronicle" means a factual historical account recorded in order, but the passage explicitly states that the memory did not faithfully record the past; calling it a chronicle would contradict the passage''s core argument. "Vessel" means a container that holds something, but the passage describes memory as actively shaping identities, not merely containing them; a vessel implies passive storage rather than the functional, politically operative role the passage attributes to collective memory.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WTNCOA', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Cuban composer Ernesto Lecuona was celebrated for his ability to blend classical European traditions with Caribbean rhythms. His most famous suite, Andalucía, is admired both for capturing the spirit of Spanish folk music and for ______ complex piano techniques that few performers of his era could master.', $lyceon_json$[{"key":"A","text":"it incorporated"},{"key":"B","text":"the incorporation of"},{"key":"C","text":"incorporating"},{"key":"D","text":"having been incorporated with"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct choice uses the gerund ''incorporating'' to maintain parallel structure with ''capturing'' in the construction ''both for capturing...and for incorporating.'' Parallel structure requires that elements joined by correlative conjunctions take the same grammatical form. The clause ''it incorporated'' breaks the parallel pattern by introducing an independent clause after the preposition ''for.'' The noun phrase ''the incorporation of'' shifts from a gerund to a nominalization, creating a subtle but real imbalance with the gerund ''capturing.'' The passive construction ''having been incorporated with'' reverses the agent relationship and introduces a perfect passive form that is not parallel with the active gerund ''capturing.''', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
